from __future__ import absolute_import

from .common_page import CommonPage
from .panels.view import ViewPanel


class Dashboard(CommonPage):
    """
    The class corresponding to Dashboard Page page on selenium_coam_cu web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            self._instance_dict = {"Dashboard": DashboardPage(driver, version)}
        super(Dashboard, self).__init__(driver, version, self._instance_dict)


class DashboardPage(object):
    """
    As a class will be called by Diagnostic, all operations Snapshot will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['view-quilt', 'Dashboard']

    def __init__(self, driver, version):
        self._view_panel = DashboardPageViewPanel(driver, version)

    def get_ru_number(self, timeout=60):
        """
        Keyword for getting RU number from dashboard status page

        :param timeout: int, timeout for getting the RU number info

        :return: str, information of RU number
        """
        return self._view_panel.get_ru_number(timeout)

    def lock_radio(self, object_name, timeout):
        """
        This method will lock the given RU object and return status

        :param object_name: str, name of the du object that will lock
        :param timeout: int, timeout for the element be available to click

        :return: str, return the lock status of RU object
        """
        return self._view_panel.lock_element("Lock radio(s)", object_name, timeout)

    def unlock_radio(self, object_name, timeout):
        """
        This method will unlock the given RU object and return status

        :param object_name: str, name of the ru object that will unlock
        :param timeout: int, timeout for the element be available to click

        :return: str, return the unlock status of RU object
        """
        return self._view_panel.unlock_element("Unlock radio(s)", object_name, timeout)

    def lock_cell(self, object_name, timeout):
        """
        This method will lock the given RU object and return status

        :param object_name: str, name of the du cell  object that will lock
        :param timeout: int, timeout for the element be available to click

        :return: str, return the lock status of cell object
        """
        return self._view_panel.lock_element("Lock cells", object_name, timeout)

    def unlock_cell(self, object_name, timeout):
        """
        This method will unlock the given RU object and return status

        :param object_name: str, name of the ru cell object that will unlock
        :param timeout: int, timeout for the element be available to click

        :return: str, return the unlock status of cell object
        """
        return self._view_panel.unlock_element("Unlock cells", object_name, timeout)

    def reset_radio(self, object_name, graceful_cell_shutdown, timeout):
        """
        This keyword will reset the cu form dashboard page

        :param object_name: str, radio object that needs to be reset
        :param graceful_cell_shutdown: bool, (optional) default value is True.If graceful cell shutdown needs to
                                       be unchecked then pass graceful_cell_shutdown=False
        :param timeout: int, timeout for the element be available to click

        :return: str, Status of the radio reset 'RMOD reset operation finished' or 'RMOD reset operation failed'
        """
        return self._view_panel.reset_radio(object_name, graceful_cell_shutdown, timeout)

    def get_user_session_information(self, timeout=60):
        """
        This keyword will give the user session information
        :param timeout: int, timeout for getting user session information
        :return: dict: Return the dict of  user information attribute and values
        """
        return self._view_panel.get_user_session_information(timeout)

    def lock_network_slicing(self, object_name, timeout):
        """
        This method will lock the given network slicing object and return status

        :param object_name: str, name of the network slicing object that will lock
        :param timeout: int, timeout for the element be available to click

        :return: str, return the lock status of network slicing object
        """
        return self._view_panel.lock_element("Lock network slicing", object_name, timeout)

    def unlock_network_slicing(self, object_name, timeout):
        """
        This method will unlock the given network slicing object and return status

        :param object_name: str, name of the network slicing object that will unlock
        :param timeout: int, timeout for the element be available to click

        :return: str, return the unlock status of network slicing object
        """
        return self._view_panel.unlock_element("Unlock network slicing", object_name, timeout)

    def reset_vdu(self, graceful_cell_shutdown, timeout):
        """
        This keyword will reset vdu.

        :param graceful_cell_shutdown: str, (optional) default value is "False".If graceful cell shutdown is needed
                                      then pass graceful_cell_shutdown=True
        :param timeout: int, timeout for the element be available to click

        :return: str, Status of the vdu 'reset vdu operation finished' or 'reset vdu operation failed'
        """
        return self._view_panel.reset_vdu(graceful_cell_shutdown, timeout)


class DashboardPageViewPanel(ViewPanel):

    def __init__(self, driver, version):
        self.driver = driver
        super(DashboardPageViewPanel, self).__init__(driver, version)

    def get_ru_number(self, timeout=60):
        """
        Keyword for getting RU number from dashboard status page

        :param timeout: int, timeout for getting the RU number info

        :return: str, information of RU number
        """
        self.wait_for_visibility(self.locator.RU_INFO, timeout)
        ru_number = self.get_text(self.locator.RU_INFO, timeout).split("\n")[0]
        self.click_enabled_element(self.locator.PRODUCT_LOGO, timeout)
        return ru_number

    def lock_element(self, lock_element, object_name, timeout):
        """
        This method will lock the given element object and return status

        :param lock_element str, type of element to be locked
        :param object_name: str, name of the element object that will lock
        :param timeout: int, timeout for the element be available to click

        :return: str, return the lock status of element object
        """
        self.click_enabled_element(self.locator.LOCK_ELEMENT_XPATH.format(lock_element), timeout)
        return self._perform_lock_unlock_reset(object_name, 'lock', timeout)

    def unlock_element(self, un_lock_element, object_name, timeout):
        """
        This method will unlock the given element object and return status

        :param un_lock_element str, type of element to be unlocked
        :param object_name: str, name of the element object that will unlock
        :param timeout: int, timeout for the element be available to click
        :return: str, return the unlock status of element object

         """
        self.click_enabled_element(self.locator.UNLOCK_ELEMENT_XPATH.format(un_lock_element), timeout)
        return self._perform_lock_unlock_reset(object_name, 'unlock', timeout)

    def _select_filtered_element(self, object_name):
        element_name = object_name.split("/")[-1]
        self.insert_text_to_enable_element(self.locator.FILTER_XPATH, element_name)
        self.wait_for_visibility(
            (self.locator.SELECT_OBJECT_XPATH.format(element_name)), timeout=60)
        for element in self.driver.find_elements_by_xpath(
                self.locator.SELECT_OBJECT_XPATH.format(element_name)):
            element.click()
            if self._verify_selected_element(object_name):
                return True
            element.click()
        return False

    def _verify_selected_element(self, object_name):
        for element in self.driver.find_elements_by_xpath(
                self.locator.SELECTED_OBJECT_XPATH.format(object_name.split("/")[-1])):
            selected = element.text.split("/")
            for index in range(0, len(selected)):
                selected[index] = selected[index].replace(" ", "")
            return all(elem in selected for elem in object_name.split("/"))
        return False

    def reset_radio(self, object_name, graceful_cell_shutdown, timeout):
        """
        This keyword will reset the given radio form dashboard page

        :param object_name: str, radio object that needs to be reset
        :param graceful_cell_shutdown: bool, (optional) default value is True.If graceful cell shutdown needs to
                                       be unchecked then pass graceful_cell_shutdown=False
        :param timeout: int, timeout for the element be available to click

        :return: str, Status of the radio reset 'RMOD reset operation finished' or 'RMOD reset operation failed'
        """
        self.click_enabled_element(self.locator.RESET_RADIO_BUTTON, timeout)
        if graceful_cell_shutdown is False:
            self.click_enabled_element(self.locator.GRACEFUL_CELL_SHUTDOWN_BUTTON)
        return self._perform_lock_unlock_reset(object_name, 'Reset Radio', timeout)

    def _perform_lock_unlock_reset(self, dist_name, operation, timeout):
        if self.element_exists(self.locator.LOCK_UNLOCK_RESET_CLEAR_FILTER_XPATH, 5):
            self.click_enabled_element(self.locator.LOCK_UNLOCK_RESET_CLEAR_FILTER_XPATH, timeout)
        self._select_filtered_element(dist_name)
        self.click_enabled_element(self.locator.OK_BUTTON_XPATH, timeout)
        self.wait_for_visibility(self.locator.LOCK_UNLOCK_RESET_OPERATION_STARTED_LABEL.format(operation), timeout)
        self.wait_for_visibility(self.locator.OPERATION_STATUS_LABEL_XPATH, timeout)
        return self.get_text(self.locator.RADIO_RESET_STATUS, timeout)

    def get_user_session_information(self, timeout):
        """
        This keyword will give the user session information
        :param timeout: int, timeout for getting user session information
        :return: dict: Return the dict of  user information attribute and values
        """
        self.click_enabled_element(self.locator.USER_COUNT_VIEW, timeout)
        user_info = ['user_name', 'role']
        user_info.extend(self.get_text_from_all_matching_elements(self.locator.USER_INFO_ATTRIBUTES))
        user_values = self.get_text_from_all_matching_elements(self.locator.USER_NAME_AND_ROLE)
        user_values.extend(self.get_text_from_all_matching_elements(self.locator.USER_INFO_VALUES))
        self.click_enabled_element(self.locator.USER_COUNT_VIEW, timeout)
        return dict(zip(user_info, user_values))

    def reset_vdu(self, graceful_cell_shutdown, timeout):
        """
        This keyword will reset vdu.

        :param graceful_cell_shutdown: str, (optional) default value is "False".If graceful cell shutdown is needed
                                      then pass graceful_cell_shutdown=True
        :param timeout: int, timeout for the element be available to click

        :return: str, Status of the vdu 'reset vdu operation finished' or 'reset vdu operation failed'
        """
        self.click_enabled_element(self.locator.RESET_VDU_XPATH, timeout)
        if graceful_cell_shutdown:
            self.click_enabled_element(self.locator.GRACEFUL_SHUTDOWN_BUTTON, timeout)
        self.click_enabled_element(self.locator.OK_BUTTON_XPATH, timeout)
        self.wait_for_visibility(self.locator.LOCK_UNLOCK_RESET_OPERATION_STARTED_LABEL.format('vDU reset'), timeout)
        reset_vdu_status = self.get_text(self.locator.OPERATION_STATUS_LABEL_XPATH, timeout)
        if self.elements_is_visible(self.locator.CLOSE_BUTTON_XPATH, timeout):
            self.click_enabled_element(self.locator.CLOSE_BUTTON_XPATH, timeout)
        return reset_vdu_status
